const title = new Text({ text: 'Law of Cosines', color: WHITE, fontSize: 36 });
title.moveTo([0, 3, 0]);

const A = [-2.6, -1.3, 0];
const B = [2.6, -1.3, 0];
const C = [0.5, 1.8, 0];
const tri = new Polygon({ vertices: [A, B, C], color: BLUE_C });
tri.setFill(BLUE_C, 0.12);
const sideA = new Text({ text: 'a', color: YELLOW, fontSize: 28 }); sideA.moveTo([1.7, 0.35, 0]);
const sideB = new Text({ text: 'b', color: YELLOW, fontSize: 28 }); sideB.moveTo([-1.25, 0.35, 0]);
const sideC = new Text({ text: 'c', color: YELLOW, fontSize: 28 }); sideC.moveTo([0, -1.65, 0]);
const angle = new Text({ text: 'C', color: ORANGE, fontSize: 26 }); angle.moveTo([0.15, 1.35, 0]);

const formula = new MathTex({ latex: 'c^2 = a^2 + b^2 - 2ab\\cos(C)' });
await formula.waitForRender(); formula.moveTo([0, -2.65, 0]);
const right = new Text({ text: 'At C = 90°:  cos(C) = 0  ⇒  c² = a² + b²', color: WHITE, fontSize: 24 });
right.moveTo([0, -3.35, 0]);

scene.add(title, tri, sideA, sideB, sideC, angle, formula, right);
const controls = new Controls(scene, { position: 'top-right', width: 250 });
